import os
import openai

def score_text_safety(text: str) -> dict:
    client = openai.OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    response = client.moderations.create(
        input=text,
        model="omni-moderation-latest"
    )
    return response.results[0].model_dump()
